/* Synthetic samples; QR copied from token_footprint/share-qr.json. */
window.TokenMeCyberDemo={qr:{"url": "https://github.com/lmf112358/TokenMe", "matrix": ["111111101111011111111001001111111", "100000100101001011001010001000001", "101110100011001101101000001011101", "101110100010001010011110101011101", "101110101111110010100100101011101", "100000101111010001001000001000001", "111111101010101010101010101111111", "000000000011010010100100000000000", "011111110000100101100000000110001", "000001010101110000011101001101111", "011101110000101100100100111010100", "000010001100101010001110111011101", "000011111101101110110101110111000", "111110000011110011001011001000111", "110010101000010101010010011101010", "110110010101100000111100011000100", "000010110010101101010011110111001", "110011001101000000011001001101111", "011001111111000001101010101110100", "001001000101111010111000011111110", "100001110111010101011110110001000", "110000011011111010000100001001101", "100010110110011101101000110011110", "101100000011100011000111011010100", "100001100001010001000011111111010", "000000001101001111110101100010111", "111111101111100100001101101010100", "100000101011010111101111100011110", "101110101001110110010100111111000", "101110101100001101001011110010001", "101110101011101010010010001100100", "100000101000100011111110010010100", "111111100101010110110011110100010"]},bundleFor:null};
// Use exact integer day amounts; monthly figures derive from those same days.
TokenMeCyberDemo.bundleFor=function(tier=3,scenario='sustained'){
  const total=[3800000,38000000,380000000,3800000000,38000000000][tier-1];
  let dates=scenario==='initial'?['2026-10-16']:scenario==='growing'?['2026-10-03','2026-10-08','2026-10-16']:
    [...Array.from({length:16},(_,i)=>`2026-09-${i+15}`),...Array.from({length:8},(_,i)=>`2026-10-${String(i*2+1).padStart(2,'0')}`)];
  if(scenario==='empty')dates=dates.filter(date=>date<'2026-10');
  if(scenario==='zero')dates=[];
  let remaining=total;
  const daily=dates.map((date,i)=>{const tokens=i===dates.length-1?remaining:Math.floor(total/dates.length);remaining-=tokens;return {date,total_tokens:tokens};});
  function view(rows){const amount=rows.reduce((s,r)=>s+r.total_tokens,0),codex=Math.floor(amount*.7);return {
    total_tokens:amount,active_days:rows.length,timezone:'UTC+08:00',daily:rows,
    first_observed_day:rows[0]?.date,last_observed_day:rows.at(-1)?.date,
    sources:[{source:'codex',total_tokens:codex},{source:'claude',total_tokens:amount-codex}]
  };}
  return {generated_at:'2026-10-16T10:00:00Z',views:scenario==='unconnected'?{}:{all:view(daily),'2026-10':view(daily.filter(row=>row.date.startsWith('2026-10')))}};
};
